class StockCache:
    def __init__(self):
        self.available = {}

    def reserve(self, sku, qty):
        current = self.available.get(sku, 0)
        if current >= qty:
            self.available[sku] = current - qty
            return True
        return False

_PRICE_CACHE = {}

def price_for(request, sku):
    key = (request.id, sku)
    if key not in _PRICE_CACHE:
        _PRICE_CACHE[key] = fetch_price(sku)
    return _PRICE_CACHE[key]

def find_orders(conn, email):
    sql = f"SELECT * FROM orders WHERE customer_email = '{email}'"
    return conn.execute(sql).fetchall()

def order_history(repo, customer_id):
    orders = repo.orders_for(customer_id)
    for order in orders:
        order.lines = repo.lines_for_order(order.id)
    return orders

