class Inventory:
    def __init__(self):
        self.counts = {}

    def take(self, item, n):
        have = self.counts.get(item, 0)
        if have >= n:
            self.counts[item] = have - n
            return True
        return False

_RATES = {}

def rate_for(req, currency):
    k = (req.id, currency)
    if k not in _RATES:
        _RATES[k] = load_rate(currency)
    return _RATES[k]

def customers_by_email(db, needle):
    q = f"SELECT id, name FROM customers WHERE email = '{needle}'"
    return db.execute(q).fetchall()

def invoices_page(repo, account_id):
    invoices = repo.invoices_for(account_id)
    for inv in invoices:
        inv.items = repo.items_for_invoice(inv.id)
    return invoices

